static inline void __flush_tlb_one(unsigned long addr)
{
  __native_flush_tlb_single(addr);
}

static inline void native_flush_tlb_single(unsigned long addr)
{
  asm volatile("invlpg (%0)" :: "r" (addr) : "memory");
}
